function Shell({ children }: { children: React.ReactNode }) { const { user, logout } = useAuthStore(); const navigate = useNavigate(); const [confirmLogout, setConfirmLogout] = useState(false); const [loggingOut, setLoggingOut] = useState(false); const toast = useToast(); if (!user) return <Navigate to="/login" replace />; const signOut = async () => { setLoggingOut(true); try { await authApi.logout(); toast.success('You have been signed out.'); } catch { toast.error('Signed out locally; the server could not be reached.') } finally { logout(); navigate('/login'); setLoggingOut(false) } }; return <div className="min-h-screen bg-background"><aside className="fixed inset-y-0 left-0 hidden w-64 border-r border-border bg-card p-5 lg:flex lg:flex-col"><div className="flex items-center gap-3 px-2 pb-10"><div className="grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground"><ShieldCheck size={20}/></div><b>Examwise</b></div><nav className="space-y-1">{nav[user.role].map(item => <NavLink key={item.href} to={item.href} className={({isActive}) => `block rounded-xl px-3 py-2.5 text-sm ${isActive ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`}>{item.label}</NavLink>)}</nav><button className="mt-auto flex gap-2 px-3 py-2 text-sm text-muted-foreground" onClick={() => setConfirmLogout(true)}><LogOut size={16}/> Sign out</button></aside><main className="min-h-screen pb-20 lg:pl-64 lg:pb-0"><div className="mx-auto max-w-7xl p-4 sm:p-5 md:p-8">{children}</div></main><nav aria-label="Mobile navigation" className="fixed inset-x-0 bottom-0 z-20 grid grid-cols-3 border-t border-border bg-card/95 p-2 backdrop-blur lg:hidden">{nav[user.role].slice(0, 3).map(item => <NavLink key={item.href} to={item.href} className={({isActive}) => `min-w-0 rounded-lg px-1 py-2 text-center text-[11px] ${isActive ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'}`}><span className="block truncate">{item.label}</span></NavLink>)}</nav><ConfirmDialog open={confirmLogout} title="Sign out?" description="Any in-progress work should be submitted before you leave." confirmLabel="Sign out" busy={loggingOut} onCancel={() => setConfirmLogout(false)} onConfirm={signOut}/></div> }
function Header({ title, description }: { title: string; description: string }) { const role = useAuthStore((state) => state.user?.role); return <header className="mb-8"><p className="text-xs font-semibold uppercase tracking-widest text-primary">{role} workspace</p><h1 className="mt-2 text-3xl font-semibold tracking-tight">{title}</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">{description}</p></header> }
function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-2xl border border-border bg-card p-5 ${className}`}>{children}</section> }
function StudentExams() { const navigate = useNavigate(); const examsQuery = useQuery({ queryKey: ['student-exams'], queryFn: async () => (await examApi.list()).data.data, retry: 1 }); return <><Header title="My exams" description="Review assigned assessments and start when you are ready."/>{examsQuery.isPending ? <div className="grid gap-4 md:grid-cols-2" aria-busy="true">{[1,2,3,4].map(item => <Card key={item}><div className="h-24 animate-pulse rounded-xl bg-muted"/></Card>)}</div> : examsQuery.isError ? <Card><div role="alert" className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-destructive">Unable to load available exams.</p><button className="rounded-lg border border-border px-3 py-2 text-sm" onClick={() => examsQuery.refetch()}>Retry</button></div></Card> : examsQuery.data?.length ? <div className="grid gap-4 md:grid-cols-2">{examsQuery.data.map(exam => <Card key={exam.id}><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-primary">{exam.subject}</p><h2 className="mt-2 font-semibold">{exam.title}</h2><p className="mt-2 text-sm text-muted-foreground">{exam.duration} minutes · {exam.status}</p></div><BookOpen className="text-primary"/></div><button className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-medium text-primary-foreground" onClick={() => navigate(`/student/exams/${exam.id}/instructions`)}>View instructions <ChevronRight size={16}/></button></Card>)}</div> : <Card><p className="py-8 text-center text-sm text-muted-foreground">No exams are available right now.</p></Card>}</> }
function Instructions() { const { id = '' } = useParams(); const navigate = useNavigate(); const examQuery = useQuery({ queryKey: ['exam', id], queryFn: async () => (await examApi.get(id)).data.data, enabled: Boolean(id), retry: 1 }); const startMutation = useMutation({ mutationFn: () => examApi.start(id), onSuccess: () => navigate(`/student/exams/${id}`) }); if (examQuery.isPending) return <><Header title="Before you begin" description="Review the assessment rules carefully before starting."/><Card className="max-w-3xl"><div className="h-40 animate-pulse rounded-xl bg-muted"/></Card></>; if (examQuery.isError || !examQuery.data) return <><Header title="Before you begin" description="Review the assessment rules carefully before starting."/><Card className="max-w-3xl"><p className="text-sm text-destructive">Unable to load this exam.</p></Card></>; const exam = examQuery.data; return <><Header title="Before you begin" description="Review the assessment rules carefully before starting."/><Card className="max-w-3xl"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-xl bg-primary/10 text-primary"><FileText/></div><div><h2 className="font-semibold">{exam.title}</h2><p className="text-sm text-muted-foreground">{exam.subject} · {exam.duration} minutes</p></div></div><div className="mt-8 grid gap-3 text-sm"><p>• Select one option for each multiple-choice question.</p><p>• Use the navigator to move between questions.</p><p>• Submit the exam when you finish.</p><p>• Your score is calculated and saved after submission.</p></div>{startMutation.isError && <p className="mt-5 text-sm text-destructive">Unable to start the exam. Try again.</p>}<button disabled={startMutation.isPending} className="mt-8 rounded-xl bg-primary px-5 py-3 text-sm font-medium text-primary-foreground disabled:opacity-60" onClick={() => startMutation.mutate()}>{startMutation.isPending ? 'Starting...' : 'Start exam'}</button></Card></> }
function Attempt() { const { id = '' } = useParams(); const navigate = useNavigate(); const [index, setIndex] = useState(0); const [answers, setAnswers] = useState<Record<string, string>>({}); const [seconds, setSeconds] = useState(0); const [deadline, setDeadline] = useState<number | null>(null); const examQuery = useQuery({ queryKey: ['exam', id], queryFn: async () => (await examApi.get(id)).data.data, enabled: Boolean(id), retry: 1 }); const questionsQuery = useQuery({ queryKey: ['exam-questions', id], queryFn: async () => (await questionApi.list(id)).data.data, enabled: Boolean(id), retry: 1 }); const submitMutation = useMutation({ mutationFn: () => { const questions = questionsQuery.data || []; return examApi.submit(id, questions.map(question => ({ questionId: question.id, value: answers[question.id] || '' }))) }, onSuccess: response => navigate(`/student/exams/${id}/result`, { replace: true, state: { submission: response.data.data } }) }); useEffect(() => { if (!examQuery.data || deadline) return; setDeadline(Date.now() + examQuery.data.duration * 60 * 1000); }, [deadline, examQuery.data]); useEffect(() => { if (!deadline) return; const update = () => setSeconds(Math.max(0, Math.ceil((deadline - Date.now()) / 1000))); update(); const timer = window.setInterval(update, 1000); return () => window.clearInterval(timer) }, [deadline]); const questions = questionsQuery.data || []; const q = questions[Math.min(index, Math.max(questions.length - 1, 0))]; const answeredCount = questions.filter(question => answers[question.id]).length; if (examQuery.isPending || questionsQuery.isPending) return <div className="mx-auto max-w-5xl"><div className="h-80 animate-pulse rounded-2xl bg-muted"/></div>; if (examQuery.isError || questionsQuery.isError || !examQuery.data) return <><Header title="Exam attempt" description="Answer the questions and submit your exam."/><Card><p className="text-sm text-destructive">Unable to load this exam attempt.</p></Card></>; if (!q) return <><Header title={examQuery.data.title} description="This exam has no questions yet."/><Card><p className="py-8 text-center text-sm text-muted-foreground">No questions are available for this exam.</p></Card></>; const submit = () => submitMutation.mutate(); return <div className="mx-auto max-w-5xl"><div className="mb-6 flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-widest text-primary">Live attempt</p><h1 className="mt-2 text-2xl font-semibold">{examQuery.data.title}</h1></div><div className="flex items-center gap-2 rounded-xl bg-amber-500/10 px-4 py-2 text-sm font-semibold text-amber-700"><Clock3 size={17}/>{Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, '0')}</div></div><div className="grid gap-6 lg:grid-cols-[1fr_260px]"><Card><div className="flex items-center justify-between text-sm text-muted-foreground"><span>Question {index + 1} of {questions.length}</span><span>{answeredCount} answered</span></div><div className="mt-3 h-2 rounded-full bg-muted"><div className="h-2 rounded-full bg-primary transition-all" style={{width: `${((index + 1) / questions.length) * 100}%`}}/></div><h2 className="mt-10 text-xl font-semibold leading-8">{q.text}</h2><div className="mt-7 space-y-3">{q.options.map(option => <button key={option} onClick={() => setAnswers(current => ({ ...current, [q.id]: option }))} className={`flex w-full items-center gap-3 rounded-xl border p-4 text-left text-sm transition ${answers[q.id] === option ? 'border-primary bg-primary/10' : 'border-border hover:bg-muted'}`}><span className={`grid size-6 place-items-center rounded-full border text-xs ${answers[q.id] === option ? 'border-primary bg-primary text-primary-foreground' : 'border-muted-foreground'}`}>{answers[q.id] === option && <Check size={14}/>}</span>{option}</button>)}</div>{submitMutation.isError && <p className="mt-5 text-sm text-destructive">Unable to submit this exam. Please try again.</p>}<div className="mt-8 flex flex-wrap items-center justify-between gap-3 border-t border-border pt-5"><button className="flex items-center gap-2 rounded-xl border border-border px-4 py-2 text-sm disabled:opacity-50" disabled={index === 0} onClick={() => setIndex(Math.max(0, index - 1))}><ChevronLeft size={16}/> Previous</button><div className="flex gap-2"><button className="rounded-xl border border-border px-4 py-2 text-sm" onClick={() => setAnswers(current => { const next = { ...current }; delete next[q.id]; return next })}><X size={15} className="mr-2 inline"/>Clear</button><button disabled={submitMutation.isPending} className="rounded-xl bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-60" onClick={() => index === questions.length - 1 ? submit() : setIndex(index + 1)}>{index === questions.length - 1 ? submitMutation.isPending ? 'Submitting...' : 'Submit exam' : 'Next'} <ChevronRight size={16} className="ml-1 inline"/></button></div></div></Card><Card><h2 className="font-semibold">Question navigator</h2><div className="mt-4 grid grid-cols-5 gap-2">{questions.map((question, i) => <button key={question.id} onClick={() => setIndex(i)} className={`grid size-9 place-items-center rounded-lg text-sm ${i === index ? 'bg-primary text-primary-foreground' : answers[question.id] ? 'bg-emerald-500/20 text-emerald-700' : 'bg-muted'}`}>{i + 1}</button>)}</div><p className="mt-6 text-xs leading-5 text-muted-foreground">Submit once you have selected your answers. The result is saved automatically.</p></Card></div></div> }
function ResultPage() { const { id = '' } = useParams(); const navigate = useNavigate(); const location = useLocation() as { state?: { submission?: { result: Result; score: number; total: number; percentage: number } } }; const resultsQuery = useQuery({ queryKey: ['my-results'], queryFn: async () => (await resultApi.mine()).data.data, retry: 1 }); const submission = location.state?.submission; const savedResult = submission?.result || resultsQuery.data?.find(result => result.examId === id) || resultsQuery.data?.[0]; const score = submission?.score ?? savedResult?.score ?? 0; const total = submission?.total ?? savedResult?.total ?? 0; const percentage = submission?.percentage ?? (total > 0 ? Math.round((score * 10000) / total) / 100 : 0); return <><Header title="Exam result" description="Your submission has been recorded successfully."/><Card className="max-w-2xl">{!savedResult && resultsQuery.isPending ? <div className="h-48 animate-pulse rounded-xl bg-muted"/> : !savedResult ? <p className="py-8 text-center text-sm text-muted-foreground">No result was found for this exam.</p> : <><div className="text-center"><div className="mx-auto grid size-16 place-items-center rounded-full bg-emerald-500/10 text-emerald-600"><Check size={30}/></div><p className="mt-5 text-5xl font-semibold">{percentage}%</p><p className="mt-2 text-sm text-muted-foreground">{savedResult.examTitle} · {score} of {total} correct</p></div><div className="mt-8 grid grid-cols-3 gap-3 text-center"><div className="rounded-xl bg-muted p-3"><b>{score}</b><p className="text-xs text-muted-foreground">Correct</p></div><div className="rounded-xl bg-muted p-3"><b>{Math.max(total - score, 0)}</b><p className="text-xs text-muted-foreground">Incorrect</p></div><div className="rounded-xl bg-muted p-3"><b>{total}</b><p className="text-xs text-muted-foreground">Total</p></div></div></>}<button className="mt-8 w-full rounded-xl border border-border px-4 py-3 text-sm" onClick={() => navigate('/student/history')}>Back to history</button></Card></> }
function History() { const resultsQuery = useQuery({ queryKey: ['my-results'], queryFn: async () => (await resultApi.mine()).data.data, retry: 1 }); return <><Header title="Exam history" description="Review your completed attempts and results."/><Card>{resultsQuery.isPending ? <div className="space-y-3" aria-busy="true">{[1,2,3].map(item => <div key={item} className="h-14 animate-pulse rounded-xl bg-muted"/>)}</div> : resultsQuery.isError ? <div role="alert" className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-destructive">Unable to load your results.</p><button className="rounded-lg border border-border px-3 py-2 text-sm" onClick={() => resultsQuery.refetch()}>Retry</button></div> : resultsQuery.data?.length ? <div className="divide-y divide-border">{resultsQuery.data.map(r => { const percentage = r.total > 0 ? Math.round((r.score * 10000) / r.total) / 100 : 0; return <div key={r.id} className="flex items-center justify-between gap-4 py-4 first:pt-0"><div><p className="font-medium">{r.examTitle}</p><p className="mt-1 text-sm text-muted-foreground">{r.subject} · {r.date} · {r.score}/{r.total}</p></div><span className="font-semibold text-emerald-600">{percentage}%</span></div> })}</div> : <p className="py-8 text-center text-sm text-muted-foreground">No completed exams yet.</p>}</Card></> }
function TeacherExams() { const navigate = useNavigate(); const queryClient = useQueryClient(); const examsQuery = useQuery({ queryKey: ['teacher-exams'], queryFn: async () => (await examApi.list()).data.data, retry: 1 }); const publishMutation = useMutation({ mutationFn: (id: string) => examApi.publish(id), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['teacher-exams'] }) }); const deleteMutation = useMutation({ mutationFn: (id: string) => examApi.remove(id), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['teacher-exams'] }) }); return <><Header title="Exam management" description="Create, edit, validate, and publish assessments."/><div className="mb-5 flex justify-end"><button onClick={() => navigate('/teacher/exams/create')} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm text-primary-foreground"><Plus size={16}/> Create exam</button></div><Card>{examsQuery.isPending ? <div className="space-y-3" aria-busy="true">{[1,2,3].map(item => <div key={item} className="h-16 animate-pulse rounded-xl bg-muted"/>)}</div> : examsQuery.isError ? <div role="alert" className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-destructive">Unable to load exams.</p><button className="rounded-lg border border-border px-3 py-2 text-sm" onClick={() => examsQuery.refetch()}>Retry</button></div> : examsQuery.data?.length ? <div className="divide-y divide-border">{examsQuery.data.map(e => <div key={e.id} className="flex flex-wrap items-center justify-between gap-4 py-4 first:pt-0"><div><p className="font-medium">{e.title}</p><p className="mt-1 text-sm text-muted-foreground">{e.subject} · {e.duration} min · {e.status} · {e.participants} participants</p></div><div className="flex gap-2"><button className="rounded-lg border border-border px-3 py-2 text-xs" onClick={() => navigate(`/teacher/exams/${e.id}/questions`)}>Questions</button><button disabled={publishMutation.isPending || e.status !== 'DRAFT'} className="rounded-lg bg-primary/10 px-3 py-2 text-xs text-primary disabled:opacity-50" onClick={() => publishMutation.mutate(e.id)}>Publish</button><button className="rounded-lg p-2 text-muted-foreground" onClick={() => deleteMutation.mutate(e.id)}><Trash2 size={15}/></button></div></div>)}</div> : <p className="py-8 text-center text-sm text-muted-foreground">No exams created yet.</p>}</Card></> }
function CreateExam() { const navigate = useNavigate(); const queryClient = useQueryClient(); const schema = z.object({ title: z.string().min(3), subject: z.string().min(2), date: z.string().optional(), duration: z.coerce.number().min(1).max(300) }); const { register, handleSubmit, formState: { errors } } = useForm({ resolver: zodResolver(schema), defaultValues: { date: new Date().toISOString().slice(0, 10), duration: 60 } }); const createMutation = useMutation({ mutationFn: (values: any) => examApi.create({ ...values, status: 'DRAFT', participants: 0 }), onSuccess: response => { queryClient.invalidateQueries({ queryKey: ['teacher-exams'] }); navigate(`/teacher/exams/${response.data.data.id}/questions`) } }); return <><Header title="Create an exam" description="Set the assessment details, then add and validate questions."/><Card className="max-w-2xl"><form className="space-y-5" onSubmit={handleSubmit(values => createMutation.mutate(values))}><label className="block text-sm font-medium">Title<input className="field mt-2" {...register('title')} placeholder="e.g. Biology midterm"/>{errors.title && <span className="text-xs text-destructive">Enter a title</span>}</label><label className="block text-sm font-medium">Subject<input className="field mt-2" {...register('subject')} placeholder="Biology"/>{errors.subject && <span className="text-xs text-destructive">Enter a subject</span>}</label><label className="block text-sm font-medium">Exam date<input className="field mt-2" type="date" {...register('date')} /></label><label className="block text-sm font-medium">Duration in minutes<input className="field mt-2" type="number" {...register('duration')} />{errors.duration && <span className="text-xs text-destructive">Enter a valid duration</span>}</label>{createMutation.isError && <p className="text-sm text-destructive">Unable to create this exam.</p>}<button disabled={createMutation.isPending} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm text-primary-foreground disabled:opacity-60"><Save size={16}/> {createMutation.isPending ? 'Saving...' : 'Save draft'}</button></form></Card></> }
function QuestionsPage() { const { id = '' } = useParams(); const queryClient = useQueryClient(); const [text, setText] = useState(''); const [options, setOptions] = useState(['', '', '', '']); const [correctIndex, setCorrectIndex] = useState(0); const questionsQuery = useQuery({ queryKey: ['exam-questions', id], queryFn: async () => (await questionApi.list(id)).data.data, enabled: Boolean(id), retry: 1 }); const createMutation = useMutation({ mutationFn: () => { const cleanedOptions = options.map(option => option.trim()).filter(Boolean); const answer = options[correctIndex]?.trim(); return questionApi.create(id, { text, options: cleanedOptions, answer }) }, onSuccess: () => { setText(''); setOptions(['', '', '', '']); setCorrectIndex(0); queryClient.invalidateQueries({ queryKey: ['exam-questions', id] }) } }); const deleteMutation = useMutation({ mutationFn: (questionId: string) => questionApi.remove(questionId), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['exam-questions', id] }) }); const cleanedOptions = options.map(option => option.trim()).filter(Boolean); const canAdd = text.trim().length > 0 && cleanedOptions.length >= 2 && Boolean(options[correctIndex]?.trim()); return <><Header title="Question authoring" description="Build multiple-choice questions and mark the correct answer."/><Card><div className="grid gap-4"><label className="block text-sm font-medium">Question text<input className="field mt-2" value={text} onChange={e => setText(e.target.value)} placeholder="Question text"/></label><div className="grid gap-3 md:grid-cols-2">{options.map((option, optionIndex) => <label key={optionIndex} className="block text-sm font-medium">Option {optionIndex + 1}<div className="mt-2 flex gap-2"><input className="field" value={option} onChange={e => setOptions(current => current.map((item, i) => i === optionIndex ? e.target.value : item))} placeholder={`Option ${optionIndex + 1}`}/><button type="button" aria-label={`Mark option ${optionIndex + 1} correct`} onClick={() => setCorrectIndex(optionIndex)} className={`grid size-11 shrink-0 place-items-center rounded-xl border ${correctIndex === optionIndex ? 'border-primary bg-primary text-primary-foreground' : 'border-border'}`}><Check size={17}/></button></div></label>)}</div>{createMutation.isError && <p className="text-sm text-destructive">Unable to add this question. Check the options and correct answer.</p>}<button disabled={!canAdd || createMutation.isPending} className="w-fit rounded-xl bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50" onClick={() => createMutation.mutate()}>Add question</button></div><div className="mt-6 space-y-3">{questionsQuery.isPending ? <div className="h-24 animate-pulse rounded-xl bg-muted"/> : questionsQuery.isError ? <p className="text-sm text-destructive">Unable to load questions.</p> : questionsQuery.data?.length ? questionsQuery.data.map((q, i) => <div key={q.id} className="flex items-start justify-between rounded-xl bg-muted p-4"><div><p className="text-xs text-primary">Question {i + 1} · MCQ</p><p className="mt-1 text-sm font-medium">{q.text}</p><p className="mt-2 text-xs text-muted-foreground">Options: {q.options.join(', ')}</p>{q.answer && <p className="mt-1 text-xs font-medium text-emerald-700">Correct answer: {q.answer}</p>}</div><button onClick={() => deleteMutation.mutate(q.id)} className="text-muted-foreground"><Trash2 size={16}/></button></div>) : <p className="rounded-xl bg-muted p-6 text-center text-sm text-muted-foreground">No questions added yet.</p>}</div></Card></> }
function Protected({ roles, children }: { roles: Role[]; children: React.ReactNode }) { const user = useAuthStore(s => s.user); const hydrated = useAuthStore(s => s.hydrated); useEffect(() => { if (!hydrated) useAuthStore.persist.rehydrate() }, [hydrated]); if (!hydrated) return <div className="grid min-h-screen place-items-center bg-background p-6"><p className="text-sm text-muted-foreground" role="status">Loading your session...</p></div>; if (!user) return <Navigate to="/login" replace/>; if (!roles.includes(user.role)) return <Navigate to={`/${user.role.toLowerCase()}/dashboard`} replace/>; return <Shell>{children}</Shell> }
